  constructor(
    private readonly traceStore: OrchestrationTraceStore,
    private readonly resultStore: OrchestrationResultStore,
  ) {}

  async markRunning(input: { requestId: string; source: "cli" | "mcp"; spec: OrchestrateWorkflowSpec }) {
    await this.resultStore.writeRunning(input);
  }

  async markCompleted(input: {
    requestId: string; source: "cli" | "mcp"; spec: OrchestrateWorkflowSpec; result: OrchestrationRunResult;
  }) {
    await this.resultStore.writeCompleted(input);
  }

  async markRunnerFailed(input: {
    requestId: string; source: "cli" | "mcp"; spec: OrchestrateWorkflowSpec; error: string; startedAt: string;
  }) {
    await this.traceStore.append(
      buildRunnerFailedOrchestrationTraceEntry({
        requestId: input.requestId,
        source: input.source,
        spec: input.spec,
        error: input.error,
        startedAt: input.startedAt,
      }),
    );
    await this.resultStore.writeRunnerFailed(input);
  }
}
```

